//! Port of the C++ `send_closure` machinery — the typed half of actor
//! communication (`td::send_closure` / `td::send_closure_later` in
//! `td/actor/impl/Scheduler-decl.h`, `Event::immediate_closure` in
//! `Event.h`).
//!
//! C++ sends a closure by naming a member function
//! (`send_closure(id, &Worker::query, x, p)`); the arguments are packed into
//! a type-erased `ImmediateClosure` and the callee is obtained with a blind
//! `static_cast` — undefined behavior if the `ActorId`'s type marker lies.
//!
//! The Rust port makes the member function a per-actor message enum
//! generated by [`crate::actor_messages!`] (one variant per handler, carrying the
//! arguments) and replaces the `static_cast` with a checked
//! `Any::downcast_mut` (possible since `Actor: Any`, via trait upcasting):
//! a lying marker panics instead of corrupting memory. Dispatch is the
//! scheduler's async event loop — [`send_closure`] runs the handler inline
//! when the destination is idle and otherwise queues it;
//! [`send_closure_later`] always queues.

use crate::actor::Actor;
use crate::actor_id::ActorRef;
use crate::event::ActorThunk;
use crate::scheduler::Scheduler;

/// A typed message to one handler of a concrete actor — the Rust replacement
/// for a C++ member-function closure (`&Worker::query` plus captured
/// arguments). Generated for each actor by [`crate::actor_messages!`].
pub trait ActorMessage: Send + 'static {
    /// The concrete actor type this message is dispatched to.
    type Actor: Actor;

    /// Call the handler with the carried arguments.
    fn dispatch(self, actor: &mut Self::Actor);
}

/// Downcast from the event's `&mut dyn Actor` to the concrete callee —
/// the replacement of the C++ `static_cast` in `ImmediateClosure::run`.
///
/// Checked in debug builds, a blind cast in release: the S37 gate measured
/// the `TypeId` check on every inline dispatch hop, where the C++ pays
/// nothing for its blind cast (the ring send_immediate benchmark — the
/// check plus its panic branch kept the dispatch from inlining). The check
/// still runs in every debug build and test, so a wrong-actor message is
/// caught during development; in release, sending to a lying `ActorId`
/// marker is UB — exactly the C++ `static_cast` semantics this port
/// mirrors (the marker names the actor's real type by protocol).
pub(crate) fn downcast<A: Actor>(actor: &mut dyn Actor) -> &mut A {
    debug_assert!(
        (actor as &dyn std::any::Any).type_id() == std::any::TypeId::of::<A>(),
        "send_closure type mismatch: the event was not addressed to a {}",
        std::any::type_name::<A>()
    );
    // SAFETY: `A` is the actor's real type (the `ActorId` marker protocol;
    // asserted above in debug builds). The cast drops the vtable, exactly
    // like the C++ `static_cast`.
    unsafe { &mut *(actor as *mut dyn Actor as *mut A) }
}

/// `td::send_closure`: run `message`'s handler on the destination actor —
/// inline right away when the actor is idle on this scheduler, otherwise
/// through its mailbox (the port of `Scheduler::send_closure_immediately`).
pub fn send_closure<'a, M, R>(actor_ref: R, message: M)
where
    M: ActorMessage,
    R: Into<ActorRef<'a>>,
{
    Scheduler::instance().send_closure_immediately(actor_ref.into(), make_thunk(message));
}

/// `td::send_closure_later`: like [`send_closure`], but always through the
/// destination's mailbox.
pub fn send_closure_later<'a, M, R>(actor_ref: R, message: M)
where
    M: ActorMessage,
    R: Into<ActorRef<'a>>,
{
    Scheduler::instance().send_closure_later(actor_ref.into(), make_thunk(message));
}

fn make_thunk<M: ActorMessage>(message: M) -> ActorThunk {
    ActorThunk::new(move |actor: &mut dyn Actor| {
        M::dispatch(message, downcast::<M::Actor>(actor));
    })
}

/// Declare a per-actor message enum: one variant per handler, plus the
/// [`ActorMessage`] impl dispatching each variant to the named handler
/// method — the Rust replacement for "a set of C++ member-function
/// closures".
///
/// ```ignore
/// actor_messages! {
///     /// Messages accepted by `Worker`.
///     pub enum WorkerMessage for Worker {
///         /// `send_closure(id, &Worker::query, x, p)`
///         Query { x: u32, p: u32 } => query(x, p),
///         /// `send_closure(id, &Worker::close)`
///         Close => close(),
///     }
/// }
/// // send_closure(&worker_id, WorkerMessage::Query { x: 2, p: 10 });
/// ```
///
/// Each item is `Variant { field: Type, ... } => handler(args...)` (or
/// `Variant => handler(args...)` with no payload). The dispatch evaluates
/// `actor.handler(args...)`, where `actor` is the destination actor: the
/// `args` may use the variant's fields by name, literals, or any
/// expression. Send with [`send_closure`] / [`send_closure_later`].
#[macro_export]
macro_rules! actor_messages {
    (
        $(#[$($enum_meta:tt)*])*
        $vis:vis enum $name:ident for $actor:ty {
            $($items:tt)*
        }
    ) => {
        $crate::__actor_messages_parse! {
            @go
            [ $(#[$($enum_meta)*])* $vis enum $name ]
            [$actor]
            actor $name
            [] []
            $($items)*
        }
    };
}

/// Implementation detail of [`actor_messages!`]: peels one item per
/// recursion, accumulating the enum arms and the dispatch arms separately.
///
/// The head (`attrs pub enum Name`), the actor type and the name are carried
/// as opaque token trees / a bare ident: `ty`/`vis` fragments may not be
/// re-matched before `]` (follow-set restriction), so only the entry macro
/// ever matches them.
#[doc(hidden)]
#[macro_export]
macro_rules! __actor_messages_parse {
    // `Variant { field: Type, ... , } => handler(args)` — the trailing comma
    // inside the braces is required (a `ty` fragment may not precede `}`).
    (
        @go [$($head:tt)*] [$($actor:tt)*] $recv:ident $name:ident
        [$($arms:tt)*] [$($dispatch:tt)*]
        $(#[$($variant_meta:tt)*])*
        $variant:ident { $($field:ident : $ty:ty),* , } => $handler:ident ( $($arg:expr),* ) ,
        $($rest:tt)*
    ) => {
        $crate::__actor_messages_parse! {
            @go
            [$($head)*] [$($actor)*] $recv $name
            [$($arms)* $(#[$($variant_meta)*])* $variant { $($field: $ty),*}, ]
            [$($dispatch)* $name :: $variant { $($field),* } => $recv.$handler($($arg),*), ]
            $($rest)*
        }
    };
    // `Variant => handler(args)`
    (
        @go [$($head:tt)*] [$($actor:tt)*] $recv:ident $name:ident
        [$($arms:tt)*] [$($dispatch:tt)*]
        $(#[$($variant_meta:tt)*])*
        $variant:ident => $handler:ident ( $($arg:expr),* ) ,
        $($rest:tt)*
    ) => {
        $crate::__actor_messages_parse! {
            @go
            [$($head)*] [$($actor)*] $recv $name
            [$($arms)* $(#[$($variant_meta)*])* $variant, ]
            [$($dispatch)* $name :: $variant => $recv.$handler($($arg),*), ]
            $($rest)*
        }
    };
    // All items consumed.
    (
        @go [$($head:tt)*] [$($actor:tt)*] $recv:ident $name:ident
        [$($arms:tt)*] [$($dispatch:tt)*]
    ) => {
        $($head)* { $($arms)* }

        impl $crate::ActorMessage for $name {
            type Actor = $($actor)*;

            fn dispatch(self, $recv: &mut Self::Actor) {
                match self {
                    $($dispatch)*
                }
            }
        }
    };
}
